import {toolBanner} from './tool-banner.mjs';
import {revisionModes,createRevision,editParagraph,acceptParagraph,revisedText,snapshot,restoreVersion,difference} from './revision-model.mjs';
import {keys,list,write,projects,recordTask} from './state.mjs';
import {esc,icon,formatDate,download} from './ui.mjs';
const $=s=>document.querySelector(s),saved=()=>list(keys.drafts).filter(d=>d.revision),name=mode=>revisionModes.find(m=>m[0]===mode)?.[1]||'修改稿';
let context,doc=null,index=0,mode='review',dirty=false,controller;
let revisionView='auto',lastRevisionContext=null;
let reducePlan='strong';
const now=()=>new Date().toISOString();
function confirmLeave(){return !dirty||window.confirm('有尚未保存的修改，离开后会丢失这些修改。仍要离开吗？');}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||!$('#revision-space')||!dirty||a.href===location.href)return;if(!confirmLeave()){e.preventDefault();e.stopImmediatePropagation();}else dirty=false;},true);
const heading=()=>{const fromReduce=(window.location?.hash||'').startsWith('#category/reduce'),category=fromReduce||mode!=='reduce'?'reduce':'aigc';return toolBanner(category,{title:fromReduce&&mode==='reduce'?'降重精修':name(mode),description:'从导师意见到逐段修改，让每一次修改都有记录。',actions:`<button class="btn secondary" data-rev-action="existing">${icon('folder',17)}选择已有成果</button><button class="btn primary" data-rev-action="new">${icon('upload',17)}导入论文</button>`});};
const revisionServices=()=>`<section class="rev-service-strip" aria-label="论文修改服务"><div class="rev-service-intro"><span class="rev-service-kicker">PAPERKNOW · 修改服务</span><h2>查重报告之后，继续完成精修</h2><p>选择修改目标，逐段核对、保存版本，再回到检测页复查。</p><div class="rev-credit-note">${icon('shield',15)}本地编辑与版本记录可用 · 在线 AI 修改服务待接入</div></div><div class="rev-service-grid"><button class="rev-service-card ${mode==='review'?'active':''}" data-rev-mode="review"><span class="rev-service-icon blue">${icon('user',21)}</span><span><b>导师意见修改</b><small>记录意见，逐段确认并导出</small><em>开始修改</em></span>${icon('arrow',16)}</button><button class="rev-service-card ${mode==='rewrite'?'active':''}" data-rev-mode="rewrite"><span class="rev-service-icon amber">${icon('pen',21)}</span><span><b>降重精修</b><small>人工编辑表达，保留原稿和历史版本</small><em>进入精修</em></span>${icon('arrow',16)}</button><button class="rev-service-card planned ${mode==='reduce'?'active':''}" data-rev-mode="reduce"><span class="rev-service-icon violet">${icon('spark',21)}</span><span><b>降 AIGC</b><small>仅提供编辑工作区，检测服务尚未接入</small><em>即将上线</em></span>${icon('arrow',16)}</button></div></section>`;
function save(label='保存修改',fromEditor=true){if(!doc)return false;try{if(fromEditor)capture();const next=snapshot(doc,crypto.randomUUID(),now(),label),rows=list(keys.drafts),at=rows.findIndex(d=>String(d.id)===next.id);if(at<0)rows.unshift(next);else rows[at]=next;write(keys.drafts,rows);doc=next;dirty=false;try{recordTask({id:'draft-'+doc.id,title:doc.title,kind:'本地修改稿保存',projectId:doc.projectId,url:'#draft/'+doc.id,status:'record'});}catch{context.notify('修改稿已保存，但操作记录未能保存。');}context.notify('版本已保存，原稿和历史版本均保留。');draw();return true;}catch(e){context.notify(e.message||'保存失败，请检查浏览器空间并导出备份。');return false;}}
function capture(){if(!doc||!$('#rev-suggestion'))return;const p=doc.paragraphs[index],patch={suggestion:$('#rev-suggestion').value,reason:$('#rev-reason').value,comment:$('#rev-comment').value,resolved:$('#rev-resolved').checked};if(Object.keys(patch).some(k=>patch[k]!==p[k])){doc=editParagraph(doc,index,patch);dirty=true;}}
function diffMarkup(a,b){const d=difference(a,b);return `<div class="rev-diff-grid"><div><b>原文变化区间</b><p>${esc(d.prefix)}<del>${esc(d.removed)}</del>${esc(d.suffix)}</p></div><div><b>修改稿变化区间</b><p>${esc(d.prefix)}<ins>${esc(d.added)}</ins>${esc(d.suffix)}</p></div></div><p class="hub-footnote">按共同前缀与后缀标记变化区间；这是文本对照，不是查重或 AI 检测结果。</p>`;}
function drawReduceCommerce(){const plans=[['strong','降重精修','本地编辑可用','对照真实来源，逐段整理表达与引用','原稿与修改版本保留'],['dual','AIGC + 重复率双降','在线服务未开放','AI 率与重复率联合处理','当前可先整理修改稿'],['bundle','查重与修改衔接','本地流程可用','查找相似来源，修改后再复查','不替代学校指定检测']];$('.dashboard').innerHTML=`<div id="revision-service">${toolBanner('reduce',{description:'上传论文或粘贴正文，选择处理方式，再进入可追溯的修改工作区。',actions:'<a class="btn secondary" href="#category/detection">先做免费查重</a><a class="btn secondary" href="#assets?scope=local">我的修改稿</a>'})}<section class="revision-plan-grid" aria-label="降重复率服务方案">${plans.map(([id,title,price,desc,status],i)=>`<button type="button" class="revision-plan-card ${i===0?'selected':''}" aria-pressed="${i===0}"><div class="revision-plan-icon">${icon(id==='dual'?'spark':id==='bundle'?'diamond':'pen',23)}</div><h2>${title}</h2><strong>${price}</strong><p>${desc}</p><span>${status}</span>${i===0?'<b class="revision-plan-badge">可用</b>':i===2?'<b class="revision-plan-badge">可用</b>':'<b class="revision-plan-badge muted">待开放</b>'}</button>`).join('')}</section><div class="revision-commerce-layout"><main><section class="card revision-submit-card"><div class="revision-report-tabs" aria-label="修改流程"><span>01　导入原文</span><span>02　逐段修改</span><span>03　保存与导出</span></div><div class="revision-service-alert">${icon('info',16)}请上传需要修改的原文，不要直接上传查重报告；当前仅支持在本地创建精修任务。</div><div class="revision-input-tabs"><button class="active" type="button" data-revision-input="file">上传论文</button><button type="button" data-revision-input="paste">粘贴文本</button></div><div class="revision-upload-zone" data-revision-drop>${icon('upload',34)}<strong>点击或拖拽文件上传</strong><small>支持 DOCX、PDF、TXT · 文件仅在当前浏览器解析</small><input id="revision-service-file" type="file" accept=".docx,.pdf,.txt"></div><textarea id="revision-service-text" hidden rows="8" maxlength="100000" placeholder="粘贴需要降重的正文内容…"></textarea><p class="revision-service-file-status" id="revision-service-file-status">尚未选择文件</p><button class="btn primary revision-submit-button" type="button" data-revision-service-action="start">进入本地精修工作区 ${icon('arrow',16)}</button><p class="hub-footnote">在线降重、AIGC 检测与自动改写尚未接入；提交不会产生扣费或虚构重复率。</p></section><section class="card revision-warm-note"><h2>温馨提示</h2><ol><li>先确认你拥有文稿和引用材料的使用权限。</li><li>降重不能替代真实引用、数据和研究结论核对。</li><li>本地精修会保留原稿、版本和导出记录。</li></ol></section></main><aside class="revision-commerce-side"><section class="card revision-bundle-card"><span class="revision-side-kicker">当前服务范围</span><h2>降重精修</h2><p>逐段对照原文与修改稿，确认后再导出。</p><strong>本地免费体验</strong><button class="btn secondary full" type="button" data-revision-service-action="start">开始精修</button><a class="btn secondary full" href="#help">查看使用说明</a></section><button class="btn primary full revision-download-button" type="button" disabled>${icon('download',17)}降重结果下载</button><section class="card revision-faq"><h2>常见问题</h2><details><summary>智能降重与降 AIGC 有什么区别？</summary><p>当前在线服务尚未接入，页面只保留流程入口，不生成检测百分比。</p></details><details><summary>修改后是否需要重新检测？</summary><p>需要。请用真实、合规的检测来源重新核对。</p></details><details><summary>原文会被上传吗？</summary><p>当前本地精修只在浏览器处理，原文件不会自动上传。</p></details></section></aside></div></div>`;const file=$('#revision-service-file'),text=$('#revision-service-text');file?.addEventListener('change',()=>{$('#revision-service-file-status').textContent=file.files[0]?`已选择：${file.files[0].name}`:'尚未选择文件';});rootRevisionServiceInput();}
function drawAigcCommerce(){$('.dashboard').innerHTML=`<div id="revision-service" class="aigc-commerce">${toolBanner('aigc',{title:'降 AI 率',actions:'<a class="btn secondary" href="#category/reduce">降重复率</a><a class="btn secondary" href="#assets?scope=local">我的修改稿</a>'})}<section class="aigc-plan-grid" aria-label="降 AI 率服务方案"><article class="aigc-plan-card selected"><div>${icon('spark',22)}</div><h2>中文表达精修</h2><strong>本地编辑可用</strong><p>保留原稿，核对事实与引用，逐段编辑修改稿。</p><b>不提供 AI 率判断</b></article><article class="aigc-plan-card"><div>${icon('book',22)}</div><h2>英文表达优化</h2><strong>在线服务未开放</strong><p>英文自动改写与检测平台对接尚未接入。</p><b>待开放</b></article><article class="aigc-plan-card"><div>${icon('layers',22)}</div><h2>AIGC + 重复率双降</h2><strong>在线服务未开放</strong><p>联合处理服务尚未接入，可先整理修改稿。</p><b>待接入</b></article></section><div class="aigc-commerce-layout"><main><section class="card aigc-platform-card"><div class="aigc-service-alert">${icon('info',16)}在线 AI 检测与自动改写尚未开放。当前可以保留原稿，进入本地逐段精修。</div><div class="aigc-platform-tabs">${['AI 检测未开放','自动改写未开放','本地精修可用'].map((label,i)=>`<span class="aigc-capability-state ${i===2?'ready':''}">${label}</span>`).join('')}</div><div class="aigc-evidence"><div class="aigc-evidence-title">把修改建立在真实研究之上</div><div class="aigc-evidence-compare"><div><strong>01　导入原稿</strong><span>导入自己的论文正文，原始文本单独保留。</span></div><div><strong>02　逐段精修</strong><span>核对论证、术语和引用，编辑并说明修改原因。</span></div><div><strong>03　保存与复查</strong><span>保存修改版本，导出后通过实际检测平台复核。</span></div></div><p>本地精修不自动生成文本，也不输出检测分数。</p></div><button class="btn primary aigc-start" type="button" data-revision-service-action="start">进入本地精修工作区 ${icon('arrow',16)}</button></section><section class="card revision-warm-note"><h2>温馨提示</h2><ol><li>不同检测平台的判定规则不同，结果需以实际平台报告为准。</li><li>降 AI 率不能替代真实研究、引用和原创表达。</li><li>本地精修会保留原稿和版本，在线检测服务开放后再提交。</li></ol></section></main><aside class="revision-commerce-side"><section class="card revision-bundle-card aigc-bundle"><span class="revision-side-kicker">当前服务范围</span><h2>有记录的表达修改</h2><p>本地编辑、原稿对照、版本记录与导出。在线检测与自动改写尚未开放。</p><strong>在线服务待接入</strong><a class="btn secondary full" href="#help">查看使用说明</a></section><button class="btn primary full revision-download-button" type="button" disabled>${icon('download',17)}降 AIGC 结果下载</button><section class="card revision-faq"><h2>常见问题</h2><details><summary>降 AI 率和降重复率有什么区别？</summary><p>两者针对的检测维度不同，当前在线检测尚未接入。</p></details><details><summary>能保证通过检测吗？</summary><p>不能保证。请以实际平台报告和导师要求为准。</p></details><details><summary>文本会自动上传吗？</summary><p>当前本地流程不会自动上传论文。</p></details></section></aside></div></div>`;rootRevisionServiceInput();}
function bindReducePlan(){const rootEl=$('#revision-service');if(!rootEl)return;const cards=[...rootEl.querySelectorAll('.revision-plan-card')];if(!cards.length)return;if(context?.service==='dual')reducePlan='dual';const sync=()=>{cards.forEach((card,i)=>{const selected=['strong','dual','bundle'][i]===reducePlan;card.classList.toggle('selected',selected);card.setAttribute('aria-pressed',String(selected));});const title=rootEl.querySelector('.hub-heading h1');const desc=rootEl.querySelector('.hub-heading p');const bundle=rootEl.querySelector('.revision-bundle-card');if(reducePlan==='dual'){if(title)title.textContent='AIGC + 重复率双降';if(desc)desc.textContent='联合处理服务尚未开放。当前可先保留原稿，逐段编辑修改。';if(bundle){bundle.querySelector('h2').textContent='AIGC+重复率双降套餐';bundle.querySelector('strong').textContent='在线服务待接入';}}else if(reducePlan==='bundle'){if(title)title.textContent='查重与修改衔接';if(desc)desc.textContent='核对真实相似来源，在修改后重新检查。';if(bundle){bundle.querySelector('h2').textContent='查重与修改衔接';bundle.querySelector('strong').textContent='本地比对与修改';}}else{if(title)title.textContent='降重复率';if(desc)desc.textContent='上传论文或粘贴正文，选择处理方式，再进入可追溯的修改工作区。';if(bundle){bundle.querySelector('h2').textContent='降重精修';bundle.querySelector('strong').textContent='本地免费体验';}}};cards.forEach((card,i)=>card.addEventListener('click',()=>{reducePlan=['strong','dual','bundle'][i];sync();}));sync();}
function rootRevisionServiceInput(){if((window.location?.hash||'').includes('category/aigc')){document.querySelector('.breadcrumb strong')?.replaceChildren(document.createTextNode('降 AI 率'));document.querySelectorAll('.sidebar .nav-link').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#category/aigc'));}bindReducePlan();const rootEl=$('#revision-service');if(!rootEl)return;rootEl.querySelectorAll('[data-revision-input]').forEach(button=>button.addEventListener('click',()=>{const paste=button.dataset.revisionInput==='paste';rootEl.querySelectorAll('[data-revision-input]').forEach(b=>b.classList.toggle('active',b===button));rootEl.querySelector('[data-revision-drop]').hidden=paste;rootEl.querySelector('#revision-service-text').hidden=!paste;}));}
export function disposeRevision(){controller?.abort();controller=null;dirty=false;doc=null;}
export const revisionHasWork=()=>!!$('#revision-space')&&dirty;
export function revisionRouteGuard(){if(!dirty||!$('#revision-space'))return true;if(!confirmLeave())return false;dirty=false;return true;}
export function mountRevision(options,id){context=options;if(options.mode)mode=options.mode;controller?.abort();controller=new AbortController();if(id){let key=id;try{key=decodeURIComponent(id);}catch{}doc=saved().find(d=>String(d.id)===key)||null;mode=doc?.mode||mode;index=0;dirty=false;}else if(!dirty){doc=null;index=0;}draw();$('.dashboard').addEventListener('click',handle,{signal:controller.signal});$('.dashboard').addEventListener('input',e=>{if(e.target.closest('#rev-edit-form')){dirty=true;$('#rev-save-state').textContent='尚未保存 · 请保存版本';}},{signal:controller.signal});}
function draw(){const rows=saved().sort((a,b)=>Date.parse(b.updatedAt)-Date.parse(a.updatedAt)),p=doc?.paragraphs[index];$('.dashboard').innerHTML=heading()+revisionServices()+`<div id="revision-space"><nav class="rev-modes" aria-label="修改任务">${revisionModes.map(([key,label,desc])=>`<button data-rev-mode="${key}" aria-pressed="${mode===key}" class="${mode===key?'selected':''}">${icon(key==='review'?'user':key==='reduce'?'shield':'pen',22)}<span><b>${label}</b><small>${desc}</small></span></button>`).join('')}</nav><div class="rev-layout"><div><section class="card rev-main"><header><h2>修改工作空间</h2><span class="rev-chip">${doc?'手动修改':'开始新修改'}</span></header><ol class="rev-steps">${['导入原文','明确要求','对照修改','确认与导出'].map((n,i)=>`<li class="${doc?i===2?'active':'':i===0?'active':''}"><span>${i+1}</span>${n}</li>`).join('')}</ol>${doc?`<div class="rev-document"><div><b>${esc(doc.title)}</b><small>${esc(projects().find(p=>p.id===doc.projectId)?.name||'未归入项目')} · ${esc(name(doc.mode))} · ${doc.paragraphs.length} 段</small></div><button class="btn secondary" data-rev-action="requirements">编辑要求</button></div><p class="rev-requirements">修改要求：${esc(doc.requirements||'尚未填写')}</p>${doc.warnings?.length?`<details class="rev-notice"><summary>导入提示（${doc.warnings.length}）</summary>${doc.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}</details>`:''}<div class="rev-toolbar"><label for="rev-paragraph">选择段落</label><select id="rev-paragraph">${doc.paragraphs.map((p,i)=>`<option value="${i}" ${i===index?'selected':''}>第 ${i+1} 段 · ${p.accepted?'已采纳':p.suggestion!==p.original?'待采纳':'原文'} — ${esc(p.original.slice(0,22))}</option>`).join('')}</select><button class="btn secondary" data-rev-action="diff">查看差异</button></div><form id="rev-edit-form"><div class="rev-editors"><section><h3>原文 <span>只读</span></h3><pre>${esc(p.original)}</pre></section><section><h3>修改稿 <span>${p.accepted?'已采纳':'手动编辑 · 待确认'}</span></h3><label class="sr-only" for="rev-suggestion">编辑当前段修改稿</label><textarea id="rev-suggestion" maxlength="20000">${esc(p.suggestion)}</textarea></section></div><div class="rev-comments"><div><label for="rev-comment">导师意见 / 待核对问题</label><textarea id="rev-comment" maxlength="2000" rows="2" placeholder="记录这段需要解决的问题…">${esc(p.comment)}</textarea></div><div><label for="rev-reason">修改说明</label><textarea id="rev-reason" maxlength="2000" rows="2" placeholder="记录修改原因与需要核对的依据…">${esc(p.reason)}</textarea></div></div><label class="rev-resolved"><input type="checkbox" id="rev-resolved" ${p.resolved?'checked':''}> 我已核对并解决本段意见（独立于是否采纳）</label></form><div class="rev-accept"><span>采纳后才会进入导出稿；继续编辑需重新确认。</span><button class="btn secondary" data-rev-action="keep">保留原文</button><button class="btn secondary" data-rev-action="accept">采纳本段</button></div><div class="rev-footer"><span id="rev-save-state" role="status">${dirty?'尚未保存 · 请保存版本':'已保存版本 · 本地浏览器'}</span><button class="btn secondary" data-rev-action="save">保存版本</button><button class="btn primary" data-rev-action="export">确认与导出</button></div>`:`<div class="rev-empty"><div class="rev-empty-icon">${icon('pen',34)}</div><h3>开始修改你的论文</h3><p>导入有权使用的论文，填写修改要求，逐段编辑和核对。</p><button class="btn primary" data-rev-action="new">${icon('plus',16)}创建修改稿</button><button class="btn secondary" data-rev-action="existing">选择已有成果</button><small>支持 DOCX / PDF / TXT 或粘贴正文；不会自动生成修改。</small></div>`}<p class="rev-notice">${mode==='reduce'?'表达优化不保证降低 AI 检测分数或通过检测，不生成推测的 AI 率。':mode==='rewrite'?'请结合真实相似来源与规范引用核对；未重新检测时不生成新的重复率。':'修改需核对引用、数据、公式和研究结论，不能用润色替代研究证据。'}</p></section><section class="card rev-versions"><header><h2>版本记录</h2>${doc?'<button class="btn secondary" data-rev-action="backup">导出完整备份</button>':''}</header>${doc?`<div class="rev-version-row"><b>原始导入文稿</b><span>${esc(formatDate(doc.createdAt))}</span><button data-rev-action="original">查看原稿</button><button data-rev-action="reset">恢复原稿</button></div>${doc.versions.slice().reverse().map((v,i)=>`<div class="rev-version-row"><b>v${doc.versions.length-i} · ${esc(v.label)}</b><span>${esc(formatDate(v.at))}</span><button data-rev-version="${esc(v.id)}">查看与恢复</button></div>`).join('')}`:'<p class="hub-footnote">创建文稿后，原稿与每次主动保存的版本会保留在这里。</p>'}</section></div><aside class="rev-side"><section class="card"><h2>最近修改</h2>${rows.length?rows.slice(0,4).map(r=>`<a href="#draft/${encodeURIComponent(r.id)}"><b>${esc(r.title)}</b><small>${esc(name(r.mode))} · ${esc(formatDate(r.updatedAt))}</small><span>继续修改 →</span></a>`).join(''):'<p>尚无修改记录。创建并保存第一份修改稿后，会显示在这里。</p>'}</section><section class="card"><h2>待核对意见</h2>${doc?doc.paragraphs.filter(p=>p.comment&&!p.resolved).map(p=>`<button class="rev-issue" data-rev-jump="${doc.paragraphs.indexOf(p)}"><b>第 ${doc.paragraphs.indexOf(p)+1} 段</b><span>${esc(p.comment.slice(0,100))}</span></button>`).join('')||'<p>暂无待核对意见。是否解决由你单独确认，采纳修改不会自动标记解决。</p>':'<p>在段落中记录导师意见与问题，方便定位修改。</p>'}</section><section class="card"><h2>当前能力</h2><p>本地编辑、逐段对照、版本保存与 TXT 导出。</p><div class="rev-notice">AI 修改尚未接入。当前不生成建议稿、重复率或 AI 率。</div><p>原始文件不保存，Word 排版与批注不会保留。请及时备份。</p></section></aside></div></div>`;
$('#rev-paragraph')?.addEventListener('change',e=>{const next=Number(e.target.value);try{capture();index=next;draw();}catch(err){context.notify(err.message);e.target.value=index;}});}
const drawWorkspace=draw;draw=function(){if(context!==lastRevisionContext){lastRevisionContext=context;revisionView='auto';}if((window.location?.hash||'').includes('category/aigc')){drawAigcCommerce();return;}if(revisionView==='auto')revisionView=context?.mode==='reduce'&&!doc?'service':'workspace';if(revisionView==='service'){drawReduceCommerce();return;}drawWorkspace();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-revision-service-action]');if(!b||!$('#revision-service'))return;if(b.dataset.revisionServiceAction==='start'){revisionView='workspace';draw();inputForm();}});
function handle(e){const b=e.target.closest('[data-rev-action],[data-rev-mode],[data-rev-version],[data-rev-jump]');if(!b)return;try{if(b.dataset.revMode){if(!confirmLeave())return;mode=b.dataset.revMode;doc=null;dirty=false;draw();return;}capture();if(b.dataset.revJump){index=Number(b.dataset.revJump);draw();return;}if(b.dataset.revVersion){versionDialog(b.dataset.revVersion);return;}switch(b.dataset.revAction){case'new':if(confirmLeave())inputForm();break;case'existing':if(confirmLeave())existingDialog();break;case'requirements':requirementsForm();break;case'save':save();break;case'accept':doc=acceptParagraph(doc,index);dirty=true;draw();break;case'keep':doc=editParagraph(doc,index,{accepted:false});dirty=true;draw();break;case'diff':context.modal('当前段落差异',diffMarkup(doc.paragraphs[index].original,doc.paragraphs[index].suggestion));break;case'export':exportDialog();break;case'backup':download(doc.title+'-修改备份.json',JSON.stringify({format:'paperknow-revision-backup',version:1,document:doc},null,2),'application/json');context.notify('已发起备份下载，包含当前编辑和历史版本。');break;case'original':context.modal('原始导入文稿',`<pre class="rev-preview">${esc(doc.original)}</pre>`);break;case'reset':{context.modal('恢复原稿',`<p>将原始导入文本恢复为当前稿，并保存新的版本。当前编辑也会先保存，历史不会覆盖。</p><button class="btn primary" id="rev-reset-confirm">恢复并保存新版本</button>`);$('#rev-reset-confirm').onclick=()=>{if(doc.versions.length>48){context.notify('剩余版本空间不足，请导出备份。');return;}if(!save('恢复前保存'))return;const base=createRevision({...doc,text:doc.original},doc.id,doc.createdAt);doc={...doc,paragraphs:base.paragraphs};dirty=true;draw();if(save('恢复原稿',false))$('#workspace-dialog').close();};break;}}}catch(err){context.notify(err.message||'操作失败，请保留原稿并重试。');}}
function fields(values={}){return `<label for="rev-title">文稿标题 *</label><input id="rev-title" maxlength="200" required value="${esc(values.title||'')}"><label for="rev-project">所属项目</label><select id="rev-project"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===values.projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select><label for="rev-requirements">修改要求 / 导师意见</label><textarea id="rev-requirements" rows="3" maxlength="5000" placeholder="填写修改目标；降重时请记录真实来源或报告位置…">${esc(values.requirements||'')}</textarea>`;}
function inputForm(source={}){let fileName='',warnings=[],busy=false;context.modal('创建'+name(mode)+'任务',`<form id="rev-create" class="hub-form">${fields(source)}<label class="lit-upload" for="rev-file">${icon('upload',20)}<span>选择文档（可选）<small> DOCX / PDF / TXT · 最大 50MB</small></span><input id="rev-file" type="file" accept=".docx,.pdf,.txt"></label><p id="rev-file-status" role="status"></p><label for="rev-input-text">论文正文 *</label><textarea id="rev-input-text" rows="8" maxlength="100000" required placeholder="粘贴正文，用空行分隔段落；最多 100,000 字符。">${esc(source.text||'')}</textarea><p class="hub-footnote">仅提取文本，不保留原始文件、排版和批注；扫描 PDF 不支持 OCR。正文不会上传，AI 尚未接入。</p><p id="rev-form-error" role="alert"></p><button class="btn primary" id="rev-create-submit">创建并保存原稿</button></form>`);const form=$('#rev-create');$('#rev-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>50*1024*1024){$('#rev-file-status').textContent='文件超过 50MB。';return;}if($('#rev-input-text').value.trim()&&!window.confirm('导入会替换表单中的正文，是否继续？'))return;busy=true;$('#rev-create-submit').disabled=true;$('#rev-file-status').textContent='正在本地解析…';try{const {extractFile}=await import('/precheck/assets/parsers.js');const result=await extractFile(file);if($('#rev-create')!==form)return;if(!result.text.trim())throw Error('未提取到正文，请核对文件或粘贴文本。');if(result.text.length>100000)throw Error('正文超过 100,000 字符，请分章节导入。');$('#rev-input-text').value=result.text;fileName=file.name;warnings=result.warnings||[];if(!$('#rev-title').value.trim())$('#rev-title').value=file.name.replace(/\.[^.]+$/,'').slice(0,200);$('#rev-file-status').textContent=`已提取 ${result.text.length} 字符，请核对正文。${warnings.length?'存在 '+warnings.length+' 条解析提示，创建后可查看。':''}`;}catch(err){if($('#rev-create')===form)$('#rev-file-status').textContent=err.message;}finally{busy=false;if($('#rev-create')===form)$('#rev-create-submit').disabled=false;}};
form.onsubmit=e=>{e.preventDefault();if(busy)return;const old=doc;try{const next=createRevision({title:$('#rev-title').value,text:$('#rev-input-text').value,requirements:$('#rev-requirements').value,projectId:$('#rev-project').value,mode,fileName,warnings,sourceId:source.id||''},crypto.randomUUID(),now());doc=next;index=0;if(save('原稿导入',false))$('#workspace-dialog').close();else doc=old;}catch(err){doc=old;$('#rev-form-error').textContent=err.message;}};}
function existingDialog(){const rows=list(keys.drafts).filter(d=>!d.revision&&String(d.text||'').trim());context.modal('选择已有成果',`<p>复制已有成果文本创建修改稿，原成果不会被覆盖。结构模板也需先核对是否包含正文。</p>${rows.length?`<div class="rev-existing">${rows.map((d,i)=>`<button data-rev-existing="${i}"><b>${esc(d.title||'未命名成果')}</b><small>${esc(formatDate(d.updatedAt))}</small></button>`).join('')}</div>`:'<p>尚无可复制的正文成果，请导入文档或粘贴正文。</p>'}`);$('#workspace-dialog-body').querySelectorAll('[data-rev-existing]').forEach(b=>b.onclick=()=>inputForm(rows[Number(b.dataset.revExisting)]));}
function requirementsForm(){context.modal('编辑修改要求',`<form id="rev-meta" class="hub-form">${fields(doc)}<button class="btn primary">应用到当前稿</button><p>应用后仍需保存版本。</p></form>`);$('#rev-meta').onsubmit=e=>{e.preventDefault();const title=$('#rev-title').value.trim();if(!title)return;doc={...doc,title,projectId:$('#rev-project').value,requirements:$('#rev-requirements').value};dirty=true;$('#workspace-dialog').close();draw();};}
function versionDialog(id){const v=doc.versions.find(v=>v.id===id);if(!v)return;context.modal('版本内容与恢复',`<p>${esc(v.label)} · ${esc(formatDate(v.at))}</p><pre class="rev-preview">${esc(revisedText(v))}</pre><p>恢复会先保存当前稿，再添加一个恢复版本，不覆盖历史。</p><button class="btn primary" id="rev-restore">恢复此版本</button>`);$('#rev-restore').onclick=()=>{if(doc.versions.length>48){context.notify('剩余版本空间不足，请导出备份。');return;}if(!save('恢复前保存'))return;doc=restoreVersion(doc,id);dirty=true;draw();if(save('恢复历史版本',false))$('#workspace-dialog').close();};}
function exportDialog(){const text=revisedText(doc),accepted=doc.paragraphs.filter(p=>p.accepted).length;context.modal('确认与导出',`<p>已采纳 ${accepted} / ${doc.paragraphs.length} 段。未采纳段落使用原文。请核对引用、数据和研究结论。</p><pre class="rev-preview">${esc(text)}</pre><button class="btn primary" id="rev-export-confirm">保存版本并导出 TXT</button><p class="hub-footnote">段落以空行分隔；不包含 Word 排版、批注或修订痕迹。</p>`);$('#rev-export-confirm').onclick=()=>{if(!save('确认导出'))return;download(doc.title+'-修改稿.txt',revisedText(doc));$('#workspace-dialog').close();context.notify('已发起 TXT 下载，请确认浏览器保存。');};}
